input.command:
git merge --no-edit origin/main 2>&1 | tail -3; git log --oneline -3; ls scripts/migrations | grep -E '^[0-9]{3}_' | sort | tail -3; 
gate(){ s=$(grep -F "$1 STATUS:" references/project-standards.md | tail -1); c=$(grep -F "$1 CHECK:" references/project-standards.md | tail -1); case "$s" in *"ANSWERED BY THE OWNER"*) echo "$1 OPEN (owner)";; *"RESOLVED UNDER DELEGATION"*) case "$c" in *"not required"*|*confirmed*) echo "$1 OPEN (delegated; ${c#*CHECK: })";; *) echo "$1 CLOSED (check: ${c:-none})";; esac;; *) echo "$1 CLOSED (${s:-no status line})";; esac; }
for n in OD-24; do gate $n; done
git log --oneline | grep -c 'T-010'; grep -n "add-parameter" scripts/db.py | head -5; python3 -c "import sys;sys.path.insert(0,'scripts');import dbcore;print(dbcore.ledger_heading_count('Delegated resolution 2026-11-12 — OD-24 how coarse a parameter is, and its quantity kinds'))"

